-- Initial schema for PostgreSQL deployments. Local development creates the same tables through SQLAlchemy.
CREATE TABLE IF NOT EXISTS projects (id SERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, prompt TEXT NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'planning', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agents (id SERIAL PRIMARY KEY, name VARCHAR(80) UNIQUE NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'idle', last_run_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id SERIAL PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, task_id VARCHAR(80) NOT NULL, description TEXT NOT NULL, priority VARCHAR(20) NOT NULL DEFAULT 'medium', status VARCHAR(32) NOT NULL DEFAULT 'pending', dependencies JSONB NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS executions (id SERIAL PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, agent VARCHAR(80) NOT NULL, status VARCHAR(32) NOT NULL, logs TEXT NOT NULL DEFAULT '', errors TEXT NOT NULL DEFAULT '', duration_ms INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memory_entries (id SERIAL PRIMARY KEY, project_id INTEGER REFERENCES projects(id) ON DELETE CASCADE, kind VARCHAR(40) NOT NULL, content TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
